{
  "model": "llama3.2:3b",
  "prompt": "Create a viral TikTok script about ancient healing herbs. Write exactly 150 words. Return as JSON with fields: hook, full_script, word_count.",
  "stream": false
}

parameters.jsCode:
// Parse Ollama response
const response = $input.item.json;
const text = response.response || '';

// Try to extract JSON
const jsonMatch = text.match(/\{[\s\S]*\}/);
let script = {hook: '', full_script: text, word_count: text.split(/\s+/).length};

if (jsonMatch) {
  try {
    script = JSON.parse(jsonMatch[0]);
  } catch(e) {
    // Keep default
  }
}

console.log('GENERATED SCRIPT:', JSON.stringify(script, null, 2));

return {
  json: {
    script_id: `script_${Date.now()}`,
    hook: script.hook || 'Ancient healing secrets revealed...',
    full_script: script.full_script || text,
    word_count: script.word_count || text.split(/\s+/).length,
    emotional_tone: 'mysterious',
    suggested_hashtags: ['ancient medicine', 'healing herbs', 'wellness'],
    timestamp: new Date().toISOString()
  }
};

// Log to console for verification
console.log('FINAL SCRIPT:', JSON.stringify($input.item.json, null, 2));
return $input.item;
